"""Parse convergence file generated by SuprConGPU."""

# Built-in modules and third-party libraries.
import os
import sys
import numpy as np
import pandas as pd
from pathlib import Path

# Custom libraries.
sys.path.insert(0, "../../")
from python_libraries.file_io import utils
from python_libraries.settings import configuration

# Global settings.

# -----------------------------------------------------------------------------
# FILE PARSING
# -----------------------------------------------------------------------------
# Parse convergence file and return pandas object, where each column is
# accessible through the column names e.g.: data['column1'].
def parse_convergence_csv(base_path: str) -> pd.DataFrame:
    # Construct full file path.
    data_path = Path(base_path) / configuration.filenames["convergence"]

    return utils.parse_general_csv(data_path)


# Parse convergence file and return dictionary. The keys of the dictionary are
# the column names. Thus, dictionary['column1'] gives the values of column1.
def parse_convergence_csv_as_dict(base_path: str) -> dict:
    convergence_data = {}

    # Check that config file exists and is readable: exit on failure.
    convergence_data_path = Path(base_path) / configuration.filenames["convergence"]
    utils.check_file(convergence_data_path)

    # Attempt to parse CSV file.
    raw_data = np.genfromtxt(convergence_data_path, delimiter=",", names=True)

    # Fetch column names and reshape data to more intuitive format.
    column_names = raw_data.dtype.names
    raw_data = raw_data.view(np.float64).reshape(len(raw_data), -1)

    # Save data in dictionary, where each key is the column name (as a
    # string), and the value is the column (as a numpy array). Example:
    # convergence_data['iteration'] gives a numpy array iteration numbers.
    num_rows, num_columns = np.shape(raw_data)
    for col_idx in range(0, num_columns):
        column_name = column_names[col_idx]

        # Recast data structure and fetch column.
        convergence_data[column_name] = raw_data[:, col_idx]

    return convergence_data


# Parse Density of States file and return dictionary. The keys of the
# dictionary are energy and dos: dos_data["energy"], dos_data["dos"]
def parse_dos(base_path: str) -> dict:
    dos_data = {}

    # Check that DOS file exists and is readable: exit on failure.
    dos_data_path = Path(base_path) / configuration.filenames["dos"]
    utils.check_file(dos_data_path)

    # Read CSV file.
    pandas_data = pd.read_csv(dos_data_path, header=0)

    # Convert to NumPy arrays.
    dos_data["energy"] = np.array(pandas_data["energy"].tolist())
    dos_data["dos"] = np.array(pandas_data["dos"].tolist())

    return dos_data